head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > scrollByColumn]<br/>가로 스크롤 시 Column 단위로 스크롤할지 설정합니다.",
    "validation" : [
        "true 설정 시 Column 단위로 스크롤 되며 일정값이 스크롤 될때 전체 Column 이 왼쪽 또는 오른쪽으로 스크롤되어야 합니다.",
        "false(기본값) 설정 시 픽셀 단위로 스크롤 되며 제일 왼쪽 Column 이 접혀서 사라지거나 펼쳐지는 방식으로 스크롤되어야 합니다.",
        "true 설정 시 오른쪽으로 스크롤 시 마지막 Column 이 표시될때까지 제일 오른쪽 Column 은 잘려서 표시되어야 합니다.",
        "true 설정 시 왼쪽으로 스크롤 시 제일 왼쪽 Column 은 전체가 표시되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        scrollByColumn: con_scrollByColumn.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (8컬럼)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:250px;height:300px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column5" value="name5"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column6" value="name6"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column7" value="name7"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column8" value="name8"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col6" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col7" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col8" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_scrollCheck_onclick = function () {
    for (let i = 1; i <= 8; i++) {
        let th = document.querySelector("th[id*='target1_column" + i + "']");
        if (th) {
            wf_body_bottom.getObj("scwin").setReturnValue("column" + i + " offsetWidth : " + th.offsetWidth + "px");
        }
    }
}



scwin.btn_scrollLeft_onclick = function () {
    target1.setScrollLeft(0);
}



scwin.btn_scrollCenter_onclick = function () {
    let scrollArea = document.querySelector("div[id*='target1_scrollX_right']");
    if (scrollArea) {
        let maxScroll = scrollArea.scrollWidth - scrollArea.clientWidth;
        let center = Math.round(maxScroll / 2);
        target1.setScrollLeft(center);
    }
}



scwin.btn_scrollRight_onclick = function () {
    let scrollArea = document.querySelector("div[id*='target1_scrollX_right']");
    if (scrollArea) {
        let maxScroll = scrollArea.scrollWidth - scrollArea.clientWidth;
        target1.setScrollLeft(maxScroll);
    }
}
